import jax
import jax.numpy as jnp

@jax.jit
def scaled_dot_product(q, k, v):
    scores = jnp.matmul(q, k.swapaxes(-1, -2)) / jnp.sqrt(q.shape[-1])
    return jnp.matmul(jax.nn.softmax(scores, axis=-1), v)

