# Regla conceptual de routing híbrido + fallback en gateway
def route_request(prompt: str, has_pii: bool, complexity_score: float) -> str:
    if has_pii:
        return "local-vllm/qwen2.5-32b"  # Privacidad estricta on-prem
    if complexity_score < 0.35:
        return "fast-tier/llama-3.1-8b"  # Barato y <200ms TTFT
    return "frontier/claude-sonnet-4"    # Razonamiento complejo

