Ray Serve.ejemplo:
from ray import serve

@serve.deployment(ray_actor_options={"num_gpus": 1}, autoscaling_config={"min_replicas": 1, "max_replicas": 4})
class LLMWorker:
    def __init__(self):
        self.engine = init_vllm_engine()
    @serve.batch(max_batch_size=16, batch_wait_timeout_s=0.02)
    async def __call__(self, prompts: list[str]) -> list[str]:
        return await self.engine.generate_batch(prompts)
